275	
276	// 台账正常打开后，保存内容中的投料请求结果被改坏：下一次查询或写入必须
277	// 返回 ErrCorruptData——即使本次访问的是另一条正常记录或另一个正常批次，
278	// 也不能忽略损坏的投料请求；被拒绝的重放不得返回损坏的保存结果，被拒绝
279	// 的写入不留业务变化、不占用请求编号，原台账内容不变。恢复后原成功请求
280	// 仍可幂等重放，被拒绝过的请求编号可以正常使用。
281	func TestFeedingRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
282		dir := t.TempDir()
283		good := setupFeedingRequestLedger(t, dir)
284		t1 := feedingRequestBaseTime()
285	
286		s, err := Open(dir)
287		if err != nil {
288			t.Fatal(err)
289		}
290		defer s.Close()
291	
292		// 打开后把 feed-1 的保存结果改坏为空对象（其余记录保持完整）。
293		bad := corruptFeedingRequestResult(t, good, func() json.RawMessage {
294			return json.RawMessage(`{}`)
295		})
296		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
297			t.Fatal(err)
298		}
299	
300		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
301		for _, batchNo := range []string{"B1", "B2"} {
302			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
303				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
304			} else if v != nil {
305				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
306			}
307		}
308		// 用原编号、原内容重放损坏的请求：不得把损坏的保存结果当成成功结果
309		// 返回，必须报损坏。
310		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三"); !errors.Is(err, ErrCorruptData) {
311			t.Fatalf("重放损坏的投料请求应返回 ErrCorruptData，得到 %v", err)
312		}
313		// 对正常批次的新写入同样不能绕过。
314		if _, err := s.AddFeeding("feed-new", "B2", "M1", "1", t1, "赵六"); !errors.Is(err, ErrCorruptData) {
315			t.Fatalf("损坏台账上写入正常批次应返回 ErrCorruptData，得到 %v", err)
316		}
317	
318		// 被拒绝的访问不改动文件、不占用请求编号。
319		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
320		if err != nil {
321			t.Fatal(err)
322		}
323		if !bytes.Equal(after, bad) {
324			t.Fatalf("被拒绝的访问不应改动台账文件")
325		}
326		if bytes.Contains(after, []byte("feed-new")) {
327			t.Fatalf("被拒绝的写入不应留下请求记录")
328		}
329	
330		// 恢复后：原成功请求仍取回第一次登记的结果，批次投料保持原样，
331		// 被拒绝过的请求编号可以正常使用并取得连续序号。
332		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
333			t.Fatal(err)
334		}
335		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
336		if err != nil {
337			t.Fatalf("恢复后重放原成功请求失败: %v", err)
338		}
339		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
340		view, err := s.GetBatch("B1")
341		if err != nil {
342			t.Fatal(err)
343		}
344		if len(view.Feedings) != 2 {
345			t.Fatalf("B1 应仍为 2 条投料，得到 %d 条", len(view.Feedings))
346		}
347		f, err := s.AddFeeding("feed-new", "B2", "M1", "1", t1, "赵六")
348		if err != nil {
349			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
350		}
351		if f.Seq != 2 || f.Grams != "1" {
352			t.Fatalf("新投料结果不正确: %+v", f)
353		}
354	}
355	
356	// 读取核对规则不改变请求内容匹配：正常台账中，用同一编号把原来的 1.000
357	// 改成数值相等的 1 再提交，仍返回 ErrRequestConflict；原内容重放仍取回
358	// 第一次的结果，批次中始终只有真正登记的投料。
359	func TestFeedingRequestResultCheckKeepsPayloadMatching(t *testing.T) {
360		dir := t.TempDir()
361		setupFeedingRequestLedger(t, dir)
362		t1 := feedingRequestBaseTime()
363	
364		s, err := Open(dir)
365		if err != nil {
366			t.Fatal(err)
367		}
368		defer s.Close()
369	
370		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
371			t.Fatalf("1.000 改成数值相等的 1 应返回 ErrRequestConflict，得到 %v", err)
372		}
373		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
374		if err != nil {
375			t.Fatalf("原内容重放应成功: %v", err)
376		}
377		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
378		view, err := s.GetBatch("B1")
379		if err != nil {
380			t.Fatal(err)
381		}
382		if len(view.Feedings) != 2 {
383			t.Fatalf("冲突不应追加投料，B1 应仍为 2 条，得到 %d 条", len(view.Feedings))
384		}
385	}
386

