func TestFeedingRequestResultCheckKeepsPayloadMatching(t *testing.T) {
	dir := t.TempDir()
	setupFeedingRequestLedger(t, dir)
	t1 := feedingRequestBaseTime()

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
